CREATE OR REPLACE FUNCTION Emp_Before_Upd_Loan_fn() RETURNS TRIGGER AS $$
Declare
Begin
  If OLD.Loan_TAmt<>NEW.Loan_TAmt Then
    NEW.Loan_BAmt := NEW.Loan_BAmt + (NEW.Loan_TAmt-OLD.Loan_TAmt);
  End If;
  If OLD.Loan_MAmt<>NEW.Loan_MAmt Then
    NEW.Loan_EDate:= ADD_MONTHS(LOCALTIMESTAMP,NEW.Loan_BAmt/NEW.Loan_MAmt);
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

