CREATE OR REPLACE FUNCTION Emp_Before_Ins_TCGrad_fn() RETURNS TRIGGER AS $$
Declare
  nODegree   NUMERIC;
Begin
  SELECT TGrad_Id INTO nODegree FROM Emp_Emp WHERE Emp_Id=NEW.Emp_Id;
  NEW.TGrad_OId := nODegree;
  UPDATE Emp_Emp Set
         TGrad_Id     = NEW.TGrad_NId  ,
         Emp_GradDays = NEW.TGrad_Days ,
         Emp_GradSDate= NEW.TGrad_SDate,
         Emp_GradCons = 0,
         Emp_GradPuns = 0
   WHERE Emp_Id=NEW.Emp_Id;
Exception
  When Others Then
    NULL;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

